    import copy
    g = [row[:] for row in grid]
    H = len(g); W = len(g[0])
    visited = [[False]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if g[r][c] != 0 and not visited[r][c]:
                color = g[r][c]
                stack = [(r,c)]; visited[r][c] = True; cells = []
                while stack:
                    x,y = stack.pop(); cells.append((x,y))
                    for dx,dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nx,ny = x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and not visited[nx][ny] and g[nx][ny]==color:
                            visited[nx][ny]=True; stack.append((nx,ny))
                rs=[x for x,y in cells]; cs=[y for x,y in cells]
                minr,maxr,minc,maxc=min(rs),max(rs),min(cs),max(cs)
                is_rect=True
                for x in range(minr,maxr+1):
                    for y in range(minc,maxc+1):
                        on_border=(x==minr or x==maxr or y==minc or y==maxc)
                        if on_border and g[x][y]!=color: is_rect=False
                        if not on_border and g[x][y]!=0: is_rect=False
                if is_rect and maxr>minr and maxc>minc:
                    fill = 7 if (maxc-minc) > (maxr-minr) else 3
                    for x in range(minr+1,maxr):
                        for y in range(minc+1,maxc):
                            g[x][y]=fill
    return g
